// Parse the hub's SSE-framed JSON-RPC reply -> the tool's JSON result. A refusal or tool error THROWS (a 403 is
// never an empty list: a silent chaser that cannot read is worse than a loud one).
const rpcOf = (raw) => {
  const line = String(raw ?? '').split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.error) throw new Error(rpc.error.message ?? 'hub error');
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'tool error');
  const out = JSON.parse(rpc.result?.content?.[0]?.text ?? '[]');
  if (!Array.isArray(out)) throw new Error('expected a list from the tool');
  return out;
};
const rawOf = (it) => it.json.data ?? it.json.body ?? '';
// The three PV-D28 reminders. Read-only: nothing here sends, countersigns, confirms or rejects.
//   (a) payment claims status=pending, recorded more than 2 days ago        -> waiting on us to confirm
//   (b) contracts status=sent, clientSigned, NOT providerSigned, sent >1 day -> waiting on our countersignature
//   (c) contracts status=sent, NOT clientSigned, sent more than 7 days ago  -> waiting on the client
const DAY = 86400000;
const now = Date.now();
const ageMs = (iso) => { const t = Date.parse(iso); return Number.isFinite(t) ? now - t : null; };
const ctx = $('Parse contracts').all();
const per = [];
$input.all().forEach((it, i) => {
  const c = ctx[it.pairedItem?.item ?? i].json;
  const payments = rpcOf(rawOf(it));
  const pay = payments.filter((p) => p.status === 'pending' && (ageMs(p.recordedAt ?? p.createdAt) ?? -1) > 2 * DAY).length;
  const sent = c.contracts.filter((k) => k.status === 'sent');
  const counter = sent.filter((k) => k.clientSigned === true && k.providerSigned === false && (ageMs(k.sentAt) ?? -1) > 1 * DAY).length;
  const unsigned = sent.filter((k) => k.clientSigned === false && (ageMs(k.sentAt) ?? -1) > 7 * DAY).length;
  if (pay + counter + unsigned > 0) per.push({ clientId: c.clientId, clientName: c.clientName, pay, counter, unsigned, total: pay + counter + unsigned });
});
if (per.length === 0) return []; // nothing qualifies -> stop, no notification
per.sort((a, b) => b.total - a.total);
const sum = (k) => per.reduce((n, c) => n + c[k], 0);
const pay = sum('pay'), counter = sum('counter'), unsigned = sum('unsigned');
const s = (n, one, many) => n + ' ' + (n === 1 ? one : many);
const parts = [];
if (pay) parts.push(s(pay, 'payment claim', 'payment claims') + ' waiting over 2 days for confirmation');
if (counter) parts.push(s(counter, 'contract', 'contracts') + ' signed by the client and waiting over 1 day for our countersignature');
if (unsigned) parts.push(s(unsigned, 'contract', 'contracts') + ' sent over 7 days ago and still unsigned by the client');
const shown = per.slice(0, 10).map((c) => c.clientName + ' (' + c.total + ')');
const more = per.length > 10 ? ', and ' + (per.length - 10) + ' more' : '';
const body = parts.join('; ') + '. Clients: ' + shown.join(', ') + more + '.';
const href = (id) => '/clients/' + id + '/billing';
const payload = {
  title: 'Billing needs attention',
  href: href(per[0].clientId),
  body,
  severity: 'warning',
  counts: { paymentsAwaitingConfirmation: pay, contractsAwaitingCountersignature: counter, contractsUnsignedByClient: unsigned },
  clients: per.map((c) => ({ id: c.clientId, name: c.clientName, payments: c.pay, countersign: c.counter, unsigned: c.unsigned })),
  links: per.slice(0, 10).map((c) => ({ label: c.clientName, href: href(c.clientId) })),
  ...(per.length === 1 ? { entityType: 'client', entityId: per[0].clientId } : {}),
};
// notify takes ONE recipient user id, so the digest is delivered once per configured recipient.
const recipients = String($env.BILLING_NOTIFY_USER_IDS || $env.NOTIFY_USER_ID || '').split(',').map((x) => x.trim()).filter(Boolean);
if (recipients.length === 0) throw new Error('billing digest has content but no recipient: set BILLING_NOTIFY_USER_IDS (or NOTIFY_USER_ID)');
return recipients.map((recipientId) => ({ json: { tenantId: $env.AGENCY_TENANT_ID, recipientId, payload } }));

const items = $input.all();
for (const it of items) {
  const raw = it.json.data ?? it.json.body ?? '';
  const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.error) throw new Error(rpc.error.message ?? 'notify failed');
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'notify failed');
}
return [{ json: { ok: true, delivered: items.length } }];
